}

widget.solution:
#include <string>
#include <vector>

void apply_fills(std::vector<Position>& book, const std::vector<Fill>& fills) {
    for (const Fill& f : fills) {
        bool found = false;
        for (Position& p : book) {
            if (p.sym == f.sym) {
                p.qty += f.qty;
                p.cash -= f.qty * f.px;
                found = true;
                break;
            }
        }
        if (!found) book.push_back(Position{f.sym, f.qty, -f.qty * f.px});
    }
}

