widget.solution:
#include <iostream>
#include <iomanip>
#include <vector>

long long total_qty(const std::vector<Order>& orders) {
    long long q = 0;
    for (const Order& o : orders) q += o.qty;
    return q;
}

double vwap(const std::vector<Order>& orders) {
    double notional = 0;
    for (const Order& o : orders) notional += o.qty * o.px;
    return notional / total_qty(orders);
}

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<Order> orders;
    for (int i = 0; i < n; ++i) {
        Order o;
        std::cin >> o.qty >> o.px;
        if (o.qty > 0) orders.push_back(o);
    }
    long long q = total_qty(orders);
    std::cout << "QTY " << q << "\n";
    if (q == 0) std::cout << "VWAP n/a\n";
    else std::cout << "VWAP " << std::fixed << std::setprecision(4) << vwap(orders) << "\n";
}

